CREATE DATABASE IF NOT EXISTS inventory_db; USE inventory_db; CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE,password VARCHAR(255)); INSERT IGNORE INTO users(username,password) VALUES('admin','admin123'); CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100)); CREATE TABLE IF NOT EXISTS suppliers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150)); CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),sku VARCHAR(80),price DECIMAL(10,2),quantity INT DEFAULT 0,minimum_stock INT DEFAULT 5); CREATE TABLE IF NOT EXISTS purchases(id INT AUTO_INCREMENT PRIMARY KEY,supplier_id INT,purchase_date DATE,total DECIMAL(10,2)); CREATE TABLE IF NOT EXISTS purchase_items(id INT AUTO_INCREMENT PRIMARY KEY,purchase_id INT,product_id INT,quantity INT,price DECIMAL(10,2)); CREATE TABLE IF NOT EXISTS sales(id INT AUTO_INCREMENT PRIMARY KEY,sale_date DATE,total DECIMAL(10,2)); CREATE TABLE IF NOT EXISTS sale_items(id INT AUTO_INCREMENT PRIMARY KEY,sale_id INT,product_id INT,quantity INT,price DECIMAL(10,2));